<template>
 <section class="freight-import">
  <h2>实际运费账单</h2><p class="hint">导入快递账单，核对后独立出账。当前订单不重复增加运费，不触发发货、生产、库存或付款。</p>
  <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="ok" role="status">{{message}}</p>
  <div class="fields"><label>承运商<select v-model.number="carrier" :disabled="busy" @change="clearPreview"><option :value="0">请选择</option><option v-for="c in companies.filter(x=>x.active!==false)" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Excel账单<input type="file" accept=".xlsx" :disabled="busy" @change="selectFile" /></label><label v-if="history.length">已导入账单<select @change="openBatch($event.target.value)"><option value="">选择查看</option><option v-for="h in history" :value="h.id" :key="h.id">#{{h.id}} {{h.filename}} · {{h.status==='confirmed'?'已确认':h.status==='partial'?'部分确认，待处理':'待核对'}}</option></select></label></div>
  <div v-if="headers.length" class="fields"><label>工作表<select v-model="sheet" @change="readColumns"><option v-for="s in sheets" :key="s">{{s}}</option></select></label><label>运单号列<select v-model.number="tracking" @change="clearPreview"><option :value="0">请选择</option><option v-for="(h,i) in headers" :value="i+1" :key="i">{{i+1}} · {{h||'无标题'}}</option></select></label><label>每票最终实际运费列（元）<select v-model.number="amount" @change="clearPreview"><option :value="0">请选择</option><option v-for="(h,i) in headers" :value="i+1" :key="i">{{i+1}} · {{h||'无标题'}}</option></select></label></div>
  <div class="actions"><button :disabled="busy||!file||!carrier||!tracking||!amount" @click="preview">解析并预览</button><button v-if="batch&&batch.status!=='confirmed'" :disabled="busy||!validRows" @click="confirm">确认{{validRows}}行并出账</button></div>
  <template v-if="batch"><h3>#{{batch.id}} {{batch.filename}} · {{batch.status==='confirmed'?'已确认':batch.status==='partial'?'部分确认，待处理':'待核对'}}</h3><p class="hint">已确认差额：¥{{money(postedTotal)}}；待确认差额：¥{{money(pendingTotal)}}。包邮只留实际成本；历史订单只核对。错误行保留待处理，修正后另行导入。</p><div class="scroll"><table><thead><tr><th>行</th><th>运单号</th><th>客户／订单</th><th>实际运费</th><th>冻结附加费</th><th>应收目标</th><th>本次差额</th><th>结果／处理</th></tr></thead><tbody><tr v-for="r in batch.rows" :key="r.row_no"><td>{{r.row_no}}</td><td>{{r.tracking_no}}</td><td>{{r.customer_name}}<br />{{r.order_no||'未匹配'}}</td><td>¥{{money(r.actual_cents)}}</td><td>¥{{money(r.surcharge_cents)}}</td><td>{{r.legacy?'历史订单仅核对':r.free_shipping?'包邮':`¥${money(r.target_cents)}`}}</td><td>{{r.error?'—':`¥${money(r.delta_cents)}`}}</td><td><span v-if="r.error" class="red">{{r.error}}</span><template v-else>{{r.legacy?'不新增客户运费':r.free_shipping?'仅留实际成本':r.delta_cents===0?'无新增收费':r.entry_id?'已出账':'待确认'}}<button v-if="r.entry_id" class="secondary" @click="reversing=r;reason=''">撤销来源</button></template></td></tr></tbody></table></div></template>
  <form v-if="reversing" class="reverse" @submit.prevent="reverse"><h3>撤销 {{reversing.tracking_no}} 的本次出账</h3><label>撤销原因<input v-model.trim="reason" required /></label><div class="actions"><button :disabled="busy||!reason">确认撤销</button><button type="button" class="secondary" @click="reversing=null">返回</button></div></form>
 </section>
</template>
<script setup>
import {computed,onMounted,ref} from 'vue'
import {apiGet,apiSend} from '../api/client'
const props=defineProps({companies:{type:Array,default:()=>[]}})
const file=ref(null),carrier=ref(0),headers=ref([]),sheets=ref([]),sheet=ref(''),tracking=ref(0),amount=ref(0),batch=ref(null),busy=ref(false),error=ref(''),message=ref(''),history=ref([]),reversing=ref(null),reason=ref('')
const money=c=>(Number(c||0)/100).toFixed(2),validRows=computed(()=>batch.value?.rows.filter(r=>!r.error&&!r.entry_id).length||0),pendingTotal=computed(()=>batch.value?.rows.filter(r=>!r.error&&!r.entry_id).reduce((n,r)=>n+r.delta_cents,0)||0),postedTotal=computed(()=>batch.value?.rows.filter(r=>r.entry_id).reduce((n,r)=>n+r.delta_cents,0)||0)
function clearPreview(){batch.value=null;message.value=''}
function form(mapped){const f=new FormData();f.append('file',file.value);f.append('carrier_id',String(carrier.value));f.append('sheet',sheet.value);if(mapped){f.append('tracking_column',String(tracking.value));f.append('amount_column',String(amount.value))}return f}
async function selectFile(e){file.value=e.target.files?.[0]||null;sheet.value='';tracking.value=0;amount.value=0;clearPreview();headers.value=[];if(file.value)await readColumns()}
async function run(action){if(busy.value)return;busy.value=true;error.value='';try{await action()}catch(e){error.value=e.message||'操作失败'}finally{busy.value=false}}
async function readColumns(){clearPreview();await run(async()=>{const r=await apiSend('/api/settings/logistics/freight-imports/preview',{body:form(false)});headers.value=r.headers;sheets.value=r.sheets;sheet.value=r.sheet})}
async function loadHistory(){const r=await apiGet('/api/settings/logistics/freight-imports');history.value=r.batches||[]}
async function preview(){await run(async()=>{batch.value=await apiSend('/api/settings/logistics/freight-imports/preview',{body:form(true)});await loadHistory()})}
async function confirm(){await run(async()=>{batch.value=await apiSend(`/api/settings/logistics/freight-imports/${batch.value.id}/confirm`,{body:{}});message.value='实际运费已确认，客户账单仅增加本次差额';await loadHistory()})}
async function openBatch(id){if(!id)return;await run(async()=>{batch.value=await apiGet(`/api/settings/logistics/freight-imports/${id}`)})}
async function reverse(){await run(async()=>{await apiSend(`/api/settings/logistics/freight-entries/${reversing.value.entry_id}/reverse`,{body:{request_key:`ui-${reversing.value.entry_id}`,reason:reason.value}});message.value='已按来源冲回；原出账记录保留，可在客户账单核对';reversing.value=null})}
onMounted(()=>run(loadHistory))
</script>
<style scoped>
.freight-import{padding:20px;margin:18px 0;border:1px solid #dce5df;background:white;border-radius:8px;color:#294234}h2{margin:0;font-size:20px}h3{font-size:15px}.hint{font-size:12px;color:#6a7a70;line-height:1.7}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}label{display:grid;gap:7px;font-size:13px}input,select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #cbd9cf;border-radius:6px}.actions{display:flex;gap:8px;margin:16px 0;flex-wrap:wrap}button{padding:8px 12px;border:1px solid #286248;background:#286248;color:white;border-radius:6px;cursor:pointer}button:disabled{opacity:.5}.secondary{background:white;color:#286248;margin:6px}.scroll{overflow-x:auto}table{width:100%;min-width:950px;font-size:12px;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #e3ebe5}th{background:#f3f7f4}.red,.error{color:#ad3529}.error{background:#fff0ed;padding:10px}.ok{background:#edf6f0;padding:10px;color:#286248}.reverse{margin-top:16px;padding:16px;background:#f5f8f5;border:1px solid #dce5df}
</style>
